#include <iostream>
#include <memory>

struct Node
{
    int value{};
    std::unique_ptr<Node> next{};
};

class LinkedList
{
public:
    ~LinkedList()
    {
        while (m_head) m_head = std::move(m_head->next);      // each step frees one node
    }

    void push_front(int value)
    {
        auto node{ std::make_unique<Node>() };
        node->value = value;
        node->next = std::move(m_head);
        m_head = std::move(node);
    }

    void print() const
    {
        for (const Node* n{ m_head.get() }; n; n = n->next.get()) std::cout << '[' << n->value << "]->";
        std::cout << "null\n";
    }

    // TODO: push_back, pop_front, remove, size, reverse

private:
    std::unique_ptr<Node> m_head{};
};

int main()
{
    LinkedList list{};
    list.push_front(9);
    list.push_front(7);
    list.push_front(3);
    list.print();
    return 0;
}
